#[async_trait]
pub trait ReplayServiceMcpServer: Send + Sync + 'static {
    async fn create_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn delete_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn drive_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn get_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn list_replay_sessions(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn pause_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn resume_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn seek_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn step_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn stop_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
    async fn update_replay_session(&self, args: Value) -> std::result::Result<Value, McpError>;
}

pub struct ReplayServiceMcpHandler<T: ReplayServiceMcpServer> { inner: Arc<T> }

impl<T: ReplayServiceMcpServer> Clone for ReplayServiceMcpHandler<T> {
    fn clone(&self) -> Self { Self { inner: Arc::clone(&self.inner) } }
}

